    bronze_gardensoilthermometer = { name = "Bronast termometer za prst", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast termometer za prst za vrtnarje." },
